using ghidra.util.task;

public class PublicAPITest : AbstractGenericTest {
	Language x86;
	Language toy;

	Program program;

	/* @Before */
	public void setUp()
    {
		x86 = getLanguage("x86:LE:64:default");
		toy = getLanguage("Toy:BE:64:default");
	}

	/* @After */
	public void tearDown()
    {
		if (program != null) {
			program.release(this);
		}
	}
	
	private static Language getLanguage(string languageName)
    {
		LanguageService languageService = DefaultLanguageService.getLanguageService();
		return languageService.getLanguage(new LanguageID(languageName));
	}

	/* @Test */
	public void testADD0()
    {
		// Mostly just test that it doesn't crash
		Assembler asm = Assemblers.getAssembler(x86);
		byte[] b =
			asm.assembleLine(x86.getDefaultSpace().getAddress(0x40000000), "ADD byte ptr [RBX],BL");
		assertNotEquals(0, b.length);
	}

	protected Address addr(long offset) {
		return program.getAddressFactory().getDefaultAddressSpace().getAddress(offset);
	}

	/* @Test */
	public void testAssembleWithDelaySlot()
    {
		program = new ProgramDB("test", toy, toy.getDefaultCompilerSpec(), this);

		InstructionIterator it;
		using (Transaction tx = program.openTransaction("Test"))
{
			program.getMemory()
					.createInitializedBlock(".text", addr(0x00400000), 0x1000, (byte) 0,
						TaskMonitor.DUMMY, false);
			Assembler asm = Assemblers.getAssembler(program);

			it = asm.assemble(addr(0x00400000),
				"brds 0x00400004",
				"add r0, #6");
		}

		List<Instruction> result = new();
		while (it.hasNext()) {
			result.add(it.next());
		}

		assertEquals(2, result.size());
		assertEquals("brds", result.get(0).getMnemonicString());
		assertEquals("_add", result.get(1).getMnemonicString());
	}
}
